DROP TRIGGER IF EXISTS guard_ppv_test_sales ON public.ppv_playback_assets;
CREATE OR REPLACE FUNCTION public.public_ppv_sales(_event_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT EXISTS(SELECT 1 FROM public.ppv_events e JOIN public.ppv_playback_assets a ON a.event_id=e.id JOIN public.cms_channels c ON c.id=e.channel_id JOIN public.ppv_channel_settings s ON s.channel_id=c.id JOIN public.ppv_platform_settings p ON p.id=true WHERE e.id=_event_id AND e.status='approved' AND e.sales_starts_at<=now() AND a.sales_enabled AND c.is_published AND c.deleted_at IS NULL AND s.enabled AND p.enabled) $$;